// Block (composition) — a centered, full-width marketing introduction.
// Container caps the inner measure; Stack owns responsive action arrangement.
import { useId, type ReactNode, type Ref } from "react";
import { Media } from "../components/Media";
import { Container } from "../layouts/Container";
import { Stack } from "../layouts/Stack";
import "./Hero.css";

export interface HeroProps {
  /** Primary marketing headline. */
  title: string;
  /** Supporting copy shown below the headline. */
  subtitle?: string;
  /** Consumer-supplied calls to action, typically Buttons. */
  actions?: ReactNode;
  /** Optional product visual, illustration, or other supporting media. */
  media?: ReactNode;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function Hero({ title, subtitle, actions, media, className, ref }: HeroProps) {
  const titleId = useId();

  return (
    <section
      ref={ref}
      aria-labelledby={titleId}
      className={className ? `sd-hero ${className}` : "sd-hero"}
    >
      <Container span={8} padding="none">
        <Stack align="center" gap="medium" className="sd-hero__content">
          {/* The headline and its supporting line are ONE unit, so they group at a tighter rung
              than the section's own (`PageHeader` is the reference). */}
          <Stack align="center" gap="x-small" className="sd-hero__heading">
            <h1 id={titleId} className="sd-hero__title sd-type-display-medium">{title}</h1>
            {subtitle && (
              <p className="sd-hero__subtitle sd-type-body-medium">{subtitle}</p>
            )}
          </Stack>
          {actions && (
            <Stack
              direction={{ small: "column", medium: "row" }}
              align="center"
              justify="center"
              gap="x-small"
              className="sd-hero__actions"
            >
              {actions}
            </Stack>
          )}
          {media && <Media className="sd-hero__media">{media}</Media>}
        </Stack>
      </Container>
    </section>
  );
}

/* Hero.css — .sd-hero (Block)
   Arrangement only: full-width section rhythm and centered text. */
.sd-hero {
  width: 100%;
  padding-block: var(--sd-space-2x-large);
  text-align: center;
}

.sd-hero__title,
.sd-hero__subtitle {
  margin: 0;
}

.sd-hero__subtitle {
  color: var(--sd-color-text-muted);
}

.sd-hero__actions,
.sd-hero__media {
  width: 100%;
}
